[CmdletBinding()]
param([Parameter(Mandatory)][string] $ServerName,[Parameter(Mandatory)][ValidateSet('healthy','open','half-open')][string] $State,[string] $FailureSignature,[string] $ConfigPath=(Join-Path (Split-Path -Parent $PSScriptRoot) 'config\agents.json'),[string] $CodexHome)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
if(-not(Get-Command Get-EcosystemStateRoot -ErrorAction SilentlyContinue)){Import-Module (Join-Path $PSScriptRoot 'AgentEcosystem.psm1') -Global}
$config=Get-EcosystemConfig -ConfigPath $ConfigPath -CodexHome $CodexHome;$root=Join-Path (Get-EcosystemStateRoot -Config $config -CodexHome $CodexHome) 'health\mcp';New-Item -ItemType Directory -Path $root -Force|Out-Null
$path=Join-Path $root ($ServerName+'.json');$lock=$path+'.lock';$stream=[IO.File]::Open($lock,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$now=[DateTime]::UtcNow;$prior=$null;if(Test-Path $path){try{$prior=Get-Content $path -Raw|ConvertFrom-Json}catch{}};$failures=@();if($prior -and $prior.PSObject.Properties['failures']){$failures=@($prior.failures|Where-Object{([DateTime]::Parse($_)).AddSeconds([int]$config.mcp.resilience.failureWindowSeconds) -gt $now})};if($State -eq 'open'){$failures+=@($now.ToString('o'))};$effectiveState=$State;if($State -eq 'open' -and $failures.Count -lt [int]$config.mcp.resilience.failureThreshold){$effectiveState='suspect'};$probeCount=0;if($effectiveState -eq 'half-open' -and $prior -and $prior.PSObject.Properties['probeSuccessCount']){$probeCount=[int]$prior.probeSuccessCount+1};$record=[ordered]@{server=$ServerName;state=$effectiveState;failureSignature=$FailureSignature;failures=$failures;probeSuccessCount=$probeCount;updatedAtUtc=$now.ToString('o');retryAfterUtc=if($effectiveState -eq 'open'){$now.AddSeconds([int]$config.mcp.resilience.circuitOpenSeconds).ToString('o')}else{$null}};$tmp=$path+'.'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllText($tmp,(($record|ConvertTo-Json -Depth 8)+[Environment]::NewLine),(New-Object Text.UTF8Encoding($false)));Move-Item $tmp $path -Force;[pscustomobject]$record}finally{$stream.Dispose()}
